// Einmal die Adresse eurer Zeiterfassung eintragen, ohne abschließenden Schrägstrich.
const platformUrl = 'https://dienstplan.hemingway-hilden.de';
// Optional: bekannte Absenderadresse exakt eintragen. Leer = alle Absender; jeder PDF-Anhang wird trotzdem inhaltlich auf Z-Bericht geprüft.
const allowedSender = '';
return $input.all().map((item, i) => ({json: {...item.json, platform_url: platformUrl.replace(/\/$/, ''), allowed_sender: allowedSender.toLowerCase()}, binary: item.binary, pairedItem: {item: i}}));

const result = [];
for (const [i, item] of $input.all().entries()) {
  const from = item.json.from;
  const sender = (from?.value?.[0]?.address || (typeof from === 'string' ? (from.match(/<([^>]+)>/)?.[1] || from) : '')).trim().toLowerCase();
  if (item.json.allowed_sender && item.json.allowed_sender !== sender) continue;
  for (const file of Object.values(item.binary || {})) {
    if (file.mimeType !== 'application/pdf' && !/\.pdf$/i.test(file.fileName || '')) continue;
    result.push({json: {platform_url: item.json.platform_url, message_id: String(item.json.messageId || item.json.headers?.['message-id'] || item.json.uid || '').slice(0, 500)}, binary: {data: file}, pairedItem: {item: i}});
  }
}
return result;

// Jeden Anhang anhand seines eigenen PDF-Textes prüfen, niemals anhand der Mail.
// Ohne eindeutigen Nachweis darf kein Upload stattfinden (auch nicht bei Lesefehlern).
const original = $('PDF-Anhaenge').item;
const text = typeof $json.text === 'string' ? $json.text : '';
const normalized = text.normalize('NFKC').replace(/[\u200B-\u200D\uFEFF]/g, '').replace(/[\s\p{Z}]+/gu, ' ');
// Bedienerberichte sind kein Ersatz für die Finanzzusammenfassung.
const summary = normalized.split(/Bediener\s*(?:\([^)]*\))?\s*<\s*[ZX]\s*1\s*>/i)[0];
const isZReport = /Finanzbericht\s*<\s*Z\s*1\s*>/i.test(summary);
const numbers = [...new Set([...summary.matchAll(/Finanzbericht\s*1\s*(\d{1,20})(?=\s|$)/gi)].map(match => match[1]))];
let reason = '';
if ($json.error || !text.trim()) reason = 'PDF-Text fehlt oder konnte nicht gelesen werden';
else if (text.length > 1000000) reason = 'PDF-Text überschreitet die erlaubte Länge';
else if (!isZReport) reason = 'Keine Finanzbericht-<Z1>-Kennung';
else if (numbers.length !== 1 || !/[1-9]/.test(numbers[0])) reason = 'Keine eindeutige Z-Berichtsnummer in der Finanzzusammenfassung';
const verified = reason === '';
return {
  json: {
    platform_url: original.json.platform_url,
    message_id: original.json.message_id,
    extracted_text: text.slice(0, 1000000),
    z_report_verified: verified,
    z_report_number: verified ? numbers[0] : null,
    z_report_filter_reason: verified ? 'Z-Bericht erkannt' : reason,
  },
  binary: original.binary,
};
